<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user=requireLogin();require_once BASE_PATH.'/includes/rental-operations-common.php';ro_require_permission('refunds.manage');$pdo=Database::connection();$invoiceFilter=(int)($_GET['invoice_id']??0);
if(is_post()){
 ro_post_guard();try{$action=(string)($_POST['action']??'');$uid=isset($user['user_id'])?(int)$user['user_id']:null;
  if($action==='request'){$id=RentalOperations::requestRefund($pdo,(int)($_POST['payment_id']??0),(float)($_POST['amount']??0),trim((string)($_POST['reason']??'')),(string)($_POST['refund_method']??''),trim((string)($_POST['transaction_reference']??''))?:null,$uid);ro_flash('success','Refund request created. It must be approved and then processed.');}
  elseif($action==='approve'){if(!hasPermission('refunds.approve'))throw new RuntimeException('You do not have permission to approve refunds.');RentalOperations::changeRefundStatus($pdo,(int)($_POST['refund_id']??0),'approved',$uid);ro_flash('success','Refund approved. A separate processing step is still required.');}
  elseif($action==='process'){if(!hasPermission('refunds.process'))throw new RuntimeException('You do not have permission to process refunds.');RentalOperations::changeRefundStatus($pdo,(int)($_POST['refund_id']??0),'processed',$uid);ro_flash('success','Refund marked processed and invoice/payment balances recalculated. Verify that money was actually returned.');}
  elseif($action==='reject'){if(!hasPermission('refunds.approve'))throw new RuntimeException('You do not have permission to reject refund requests.');RentalOperations::changeRefundStatus($pdo,(int)($_POST['refund_id']??0),'rejected',$uid);ro_flash('success','Refund request rejected.');}
  else throw new RuntimeException('Unknown refund action.');
 }catch(Throwable $e){ro_flash('danger',$e->getMessage());}redirect('admin/refunds.php'.($invoiceFilter?'?invoice_id='.$invoiceFilter:''));
}
$where=$invoiceFilter?'AND i.invoice_id = ?':'';$stmt=$pdo->prepare("SELECT p.payment_id,p.payment_number,p.amount,p.status AS payment_status,p.payment_method,p.invoice_id,i.invoice_number,i.currency,c.first_name,c.last_name,COALESCE((SELECT SUM(pr.amount) FROM payment_refunds pr WHERE pr.payment_id=p.payment_id AND pr.status IN ('requested','approved','processed')),0) AS reserved_refunds FROM payments p JOIN invoices i ON i.invoice_id=p.invoice_id JOIN customers c ON c.customer_id=i.customer_id WHERE p.status IN ('completed','partially_refunded') $where ORDER BY p.payment_date DESC LIMIT 200");$stmt->execute($invoiceFilter?[$invoiceFilter]:[]);$availablePayments=$stmt->fetchAll(PDO::FETCH_ASSOC);
$eligiblePayments=array_values(array_filter($availablePayments,static fn($p)=>max(0,(float)$p['amount']-(float)$p['reserved_refunds'])>0.009));
$stmt=$pdo->prepare("SELECT pr.*,p.payment_number,p.amount AS payment_amount,i.invoice_number,i.currency,c.first_name,c.last_name,u.first_name AS requester_first,u.last_name AS requester_last,ap.first_name AS approver_first,ap.last_name AS approver_last FROM payment_refunds pr JOIN payments p ON p.payment_id=pr.payment_id JOIN invoices i ON i.invoice_id=p.invoice_id JOIN customers c ON c.customer_id=i.customer_id LEFT JOIN users u ON u.user_id=pr.requested_by LEFT JOIN users ap ON ap.user_id=pr.approved_by WHERE 1=1 ".($invoiceFilter?'AND i.invoice_id = ? ':'').'ORDER BY pr.refund_id DESC LIMIT 200');$stmt->execute($invoiceFilter?[$invoiceFilter]:[]);$refunds=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Refunds';$currentPage='refunds';require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><section class="ro-page-heading"><div><span class="ro-kicker">REFUND CONTROL</span><h1>Refunds</h1><p>Separate the request, approval and processing steps to maintain an auditable financial trail.</p></div><div class="ro-heading-symbol"><i class="bi bi-arrow-counterclockwise"></i></div></section>
<section class="ro-panel mb-4"><div class="ro-panel-head"><div><span class="ro-kicker">NEW REQUEST</span><h2>Request a payment refund</h2><p>Only the unrefunded amount is eligible. Pending and approved requests reserve part of that amount.</p></div></div><?php if(!$eligiblePayments): ?><div class="ro-empty compact"><div class="ro-empty-icon"><i class="bi bi-check2-circle"></i></div><strong>No eligible payments</strong><p>Completed payments with refundable value will appear here.</p></div><?php else: ?><form method="post" class="ro-form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="request"><div class="ro-field ro-field-wide"><label for="payment_id">Payment *</label><select class="form-select" id="payment_id" name="payment_id" required><?php foreach($eligiblePayments as $p): $remaining=max(0,(float)$p['amount']-(float)$p['reserved_refunds']); ?><option value="<?= (int)$p['payment_id'] ?>"><?= e($p['payment_number'].' · '.$p['invoice_number'].' · '.$p['first_name'].' '.$p['last_name'].' · refundable '.number_format($remaining,2).' '.$p['currency']) ?></option><?php endforeach; ?></select></div><div class="ro-field"><label for="amount">Refund amount *</label><input class="form-control" id="amount" name="amount" type="number" min="0.01" step="0.01" required></div><div class="ro-field"><label for="refund_method">Refund method *</label><select class="form-select" id="refund_method" name="refund_method" required><?php foreach(['original_method'=>'Original payment method','cash'=>'Cash','bank_transfer'=>'Bank transfer','card'=>'Card','mobile_money'=>'Mobile money','other'=>'Other'] as $v=>$label): ?><option value="<?= e($v) ?>"><?= e($label) ?></option><?php endforeach; ?></select></div><div class="ro-field ro-field-full"><label for="reason">Reason *</label><textarea class="form-control" id="reason" name="reason" rows="2" maxlength="500" required placeholder="Reason for refund and supporting reference"></textarea></div><div class="ro-field ro-field-full"><label for="transaction_reference">Refund transaction reference</label><input class="form-control" id="transaction_reference" name="transaction_reference" maxlength="150" placeholder="Reference after refund is initiated, if available"></div><div class="ro-form-actions"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-send me-1"></i> Submit refund request</button></div></form><?php endif; ?></section>
<section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">REFUND REGISTER</span><h2>Refund requests</h2></div><span class="ro-counter"><?= count($refunds) ?> records</span></div><?php if(!$refunds): ?><div class="ro-empty"><div class="ro-empty-icon"><i class="bi bi-arrow-counterclockwise"></i></div><strong>No refund requests</strong><p>Requests will appear here with their approval and processing status.</p></div><?php else: ?><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Refund</th><th>Payment / invoice</th><th>Customer</th><th>Amount</th><th>Method</th><th>Reason</th><th>Status</th><th>Requested by</th><th>Actions</th></tr></thead><tbody><?php foreach($refunds as $r): ?><tr><td><strong><?= e($r['refund_number']) ?></strong><small class="d-block text-secondary"><?= e(ro_date($r['created_at'])) ?></small></td><td><?= e($r['payment_number']) ?><small class="d-block"><a class="ro-text-link" href="<?= e(base_url('admin/invoice-view.php?id='.(int)$r['invoice_id'])) ?>"><?= e($r['invoice_number']) ?></a></small></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><strong><?= ro_money($r['amount'],$r['currency']) ?></strong></td><td><?= e(ucwords(str_replace('_',' ',$r['refund_method']))) ?></td><td class="ro-reason-cell"><?= e($r['reason']) ?></td><td><?= ro_status_badge($r['status']) ?></td><td><?= e(trim(($r['requester_first']??'').' '.($r['requester_last']??''))?:'System') ?></td><td><div class="ro-inline-actions"><?php if($r['status']==='requested'&&hasPermission('refunds.approve')): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="approve"><input type="hidden" name="refund_id" value="<?= (int)$r['refund_id'] ?>"><button class="btn btn-sm ro-btn-primary" type="submit">Approve</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="reject"><input type="hidden" name="refund_id" value="<?= (int)$r['refund_id'] ?>"><button class="btn btn-sm ro-btn-outline" type="submit">Reject</button></form><?php elseif($r['status']==='approved'&&hasPermission('refunds.process')): ?><form method="post" onsubmit="return confirm('Confirm the refund has actually been sent to the customer?')"><?= csrf_field() ?><input type="hidden" name="action" value="process"><input type="hidden" name="refund_id" value="<?= (int)$r['refund_id'] ?>"><button class="btn btn-sm ro-btn-primary" type="submit">Mark processed</button></form><?php else: ?><span class="text-secondary small">—</span><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php require BASE_PATH.'/includes/footer.php'; ?>
